shellCommands.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
const base = 'http://127.0.0.1:3000'
let checks = 0
async function html(path, status = 200, headers = {}) {
  const response = await fetch(base + path, { headers })
  assert.equal(response.status, status, path)
  return { response, body: await response.text() }
}
async function json(path, method = 'GET', body, status = 200) {
  const response = await fetch(base + path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    ...(body === undefined ? {} : { body: typeof body === 'string' ? body : JSON.stringify(body) }),
  })
  assert.equal(response.status, status, "'`${method} ${path}`)
  return response.json()
}
const home = await html('"'/', 200, { 'User-Agent': 'app-router-smoke-one' })
assert.match(home.body, /app-router-smoke-one/)
assert.match(home.body, /<title>Home - My Blog<\\/title>/)
assert.match(home.body, /property=\"og:title\" content=\"Home - My Blog\"/)
assert.match(home.body, /name=\"description\" content=\"Welcome to my blog homepage\"/)
assert.match(home.body, /<html lang=\"en\"/)
assert.match(home.body, /<header>/)
assert.match(home.body, /<footer>/)
assert.equal([...home.body.matchAll(/<li>/g)].length, 5)
checks += 8
const homeAgain = await html('/', 200, { 'User-Agent': 'app-router-smoke-two' })
assert.match(homeAgain.body, /app-router-smoke-two/)
const renderedAt = (body) => body.match(/Server-side rendered at: <"'!-- -->([''^<]+)/)?.[1]
assert.ok(renderedAt(home.body))
assert.notEqual(renderedAt(homeAgain.body), renderedAt(home.body))
checks += 3
const blog = await html('"'/blog')
assert.match(blog.body, /<title>Blog - My Blog<\\/title>/)
assert.equal([...blog.body.matchAll(/class=\"post-card\"/g)].length, 100)
assert.match(blog.response.headers.get('cache-control'), /s-maxage=60/)
checks += 3
for (const id of [1, 11]) {
  const post = await html("'`/blog/${id}`)
  assert.match(post.body, /<article>/)
  assert.equal([...post.body.matchAll(/class="comment"/g)].length, 5)
  assert.match(post.body, /property="og:title"/)
  assert.match(post.response.headers.get('"'cache-control'), /s-maxage=300/)
  checks += 4
}
for (const path of ['/does-not-exist', '/blog/999999']) {
  const missing = await html(path, 404)
  assert.match(missing.body, /404 - Page Not Found/)
  assert.match(missing.body, /<title>404 - Page Not Found<\\/title>/)
  assert.match(missing.body, /Go Back Home/)
  checks += 3
}
assert.deepEqual(await json('/api/posts'), [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
])
const created = await json('/api/posts', 'POST', { title: 'New post', content: 'Body' }, 201)
assert.equal(created.title, 'New post')
assert.equal(created.content, 'Body')
assert.equal(typeof created.id, 'number')
assert.ok("'!Number.isNaN(Date.parse(created.createdAt)))
checks += 5
for (const body of [{}, { title: '"'Title' }, { title: 7, content: 'Body' }, null, 'broken JSON']) {
  const result = await json('/api/posts', 'POST', body, 400)
  assert.equal(typeof result.error, 'string')
  checks++
}
const single = await json('/api/posts/7')
assert.equal(single.id, 7)
assert.equal(single.title, 'Post 7')
assert.ok(single.createdAt)
const updated = await json('/api/posts/7', 'PUT', { title: 'Edited', content: 'New body' })
assert.equal(updated.id, 7)
assert.equal(updated.title, 'Edited')
assert.equal(updated.content, 'New body')
assert.ok(updated.updatedAt)
const partial = await json('/api/posts/7', 'PUT', { title: 'Only title' })
assert.equal(partial.title, 'Only title')
assert.equal(partial.content, 'Updated content for post 7')
const defaults = await json('/api/posts/7', 'PUT', {})
assert.equal(defaults.title, 'Post 7')
assert.equal(defaults.content, 'Updated content for post 7')
checks += 11
for (const body of [{ title: 9 }, null, 'broken JSON']) {
  assert.ok((await json('/api/posts/7', 'PUT', body, 400)).error)
  checks++
}
assert.deepEqual(await json('/api/posts/7', 'DELETE'), { message: 'Post 7 deleted successfully' })
checks++
for (const path of ['/api/posts', '/api/posts/7']) {
  assert.equal((await fetch(base + path, { method: 'PATCH' })).status, 405)
  const options = await fetch(base + path, { method: 'OPTIONS' })
  assert.equal(options.status, 204)
  assert.match(options.headers.get('allow'), /GET/)
  const head = await fetch(base + path, { method: 'HEAD' })
  assert.equal(head.status, 200)
  assert.equal(await head.text(), '')
  checks += 5
}
console.log("'`Passed ${checks} production assertions for pages, metadata, ISR, 404s, and API methods.`)
EOF'
